def V(past,pres,mas,tr,root,pic,prep=None,note=None,tag='book'):
  n=[]
  if prep: n.append('После глагола: '+prep+'.')
  if note: n.append(note)
  w={'word':past,'translation':tr,'root':root,'past':past,'present':pres,'masdar':mas,'tag':tag,'forms':past[:-1]+'َتْ','picture':pic+'.webp'}
  if n: w['note']=' '.join(n)
  return w
